/// Connects the flag and the login hook. Call once during startup, next to the other
/// [RiseAppModule] callbacks.
static void install() {
  ChartLibraryWarmer.isEnabled = () => isEnabled;
  ChartController.selfHealEnabled = () => !isSelfHealDisabled;
  // Fires as the login request is sent and runs in parallel with it. Never awaited: the warm-up
  // reports its own failures and a login must not wait for a download.
  RiseAppModule.onLoginStart = () => ChartLibraryWarmer.warm(trigger: 'login');
}

